const src = (typeof $json.body === 'object' && $json.body !== null) ? $json.body : $json;
const yes = src.includeImage === true || /^(yes|true|1)$/i.test(String(src.includeImage||''));
return [{ json: {
  subject: src.subject || 'New GRC content draft',
  title: src.title || src.subject || 'GRC Update',
  body: src.body || '',
  to: src.to || 'michael.peters@lazarusalliance.com',
  includeImage: yes ? 'yes' : 'no'
}}];

const IMAGE_URL = '';

const N = $('Normalize Inputs').item.json;
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function inline(s){
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g,'<a href="$2" style="color:#2563eb;text-decoration:none;">$1</a>');
  s = s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>');
  s = s.replace(/`([^`]+)`/g,'<code style="background:#f1f5f9;padding:1px 4px;border-radius:4px;">$1</code>');
  return s;
}
function md2html(md){
  const lines = String(md||'').replace(/\r/g,'').split('\n');
  let html='', i=0, inList=false, lt='';
  function closeL(){ if(inList){ html += (lt==='ol'?'</ol>':'</ul>'); inList=false; } }
  while(i<lines.length){
    let ln = lines[i];
    if(/^\s*(---|\*\*\*|___)\s*$/.test(ln)){ closeL(); html+='<hr style="border:none;border-top:1px solid #e2e8f0;margin:18px 0;">'; i++; continue; }
    let h = ln.match(/^\s*(#{1,6})\s+(.*)$/);
    if(h){ closeL(); const lvl=h[1].length; const sz={1:'23px',2:'19px',3:'16px',4:'15px',5:'14px',6:'13px'};
      html+='<h'+lvl+' style="font-size:'+(sz[lvl]||'16px')+';font-weight:800;color:#0f172a;margin:20px 0 8px;line-height:1.3;">'+inline(esc(h[2]))+'</h'+lvl+'>'; i++; continue; }
    let ol = ln.match(/^\s*\d+[.)]\s+(.*)$/);
    let ul = ln.match(/^\s*[-*+]\s+(.*)$/);
    if(ol||ul){ const t = ol?'ol':'ul';
      if(!inList || lt!==t){ closeL(); html += (t==='ol'?'<ol':'<ul')+' style="margin:8px 0;padding-left:24px;color:#1f2937;font-size:14px;line-height:1.6;">'; inList=true; lt=t; }
      html+='<li style="margin:4px 0;">'+inline(esc(ol?ol[1]:ul[1]))+'</li>'; i++; continue; }
    if(/^\s*$/.test(ln)){ closeL(); i++; continue; }
    closeL();
    html+='<p style="margin:0 0 11px;color:#1f2937;font-size:14px;line-height:1.65;">'+inline(esc(ln))+'</p>'; i++;
  }
  closeL();
  return html;
}
