const bodyHtml = md2html(N.body||'');
const img = IMAGE_URL ? '<img src="'+IMAGE_URL+'" alt="Featured image" width="760" style="display:block;width:100%;max-width:760px;height:auto;border:0;">' : '';
const html =
'<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;max-width:760px;margin:0 auto;background:#f8fafc;padding:24px;color:#0f172a;">'+
  '<div style="background:#0f172a;border-radius:14px 14px 0 0;padding:22px 28px;">'+
    '<div style="color:#93c5fd;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;">Lazarus Alliance &middot; GRC Content Studio</div>'+
    '<div style="color:#fff;font-size:22px;font-weight:800;margin-top:6px;line-height:1.3;">'+title+'</div>'+
  '</div>'+ img +
  '<div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 14px 14px;padding:20px 28px 26px;">'+ bodyHtml +'</div>'+
  '<div style="font-size:11px;color:#94a3b8;padding:12px 4px;">Drafted by the Lazarus Alliance GRC Content Studio. Review before publishing.</div>'+
